        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_OnApplicationWillTerminate">SDL_OnApplicationWillTerminate</seealso></SDLWiki>
        public static extern void OnApplicationWillTerminate();

        /// <summary>
        /// <para>Request permissions at runtime, asynchronously.</para>
        /// </summary>
        /// <remarks>
        /// <para>You do not need to call this for built-in functionality of SDL; recording from a microphone or reading images from a camera, using standard SDL APIs, will manage permission requests for you.</para>
        /// <para>This function never blocks. Instead, the app-supplied callback will be called when a decision has been made. This callback may happen on a different thread, and possibly much later, as it might wait on a user to respond to a system dialog. If permission has already been granted for a specific entitlement, the callback will still fire, probably on the current thread and before this function returns.</para>
        /// <para>If the request submission fails, this function returns false and the callback will NOT be called, but this should only happen in catastrophic conditions, like memory running out. Normally there will be a yes or no to the request through the callback.</para>
        /// <para>For the <c>permission</c> parameter, choose a value from here:</para>
        /// <para>https://developer.android.com/reference/android/Manifest.permission</para>
        /// </remarks>
        /// <param name="permission">the permission to request.</param>
        /// <param name="cb">the callback to trigger when the request has a response.</param>
        /// <param name="userdata">an app-controlled pointer that is passed to the callback.</param>
        /// <returns>
        /// <para>(bool) Returns true if the request was submitted, false if there was an error submitting. The result of the request is only ever reported through the callback, not this return value.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_RequestAndroidPermission">SDL_RequestAndroidPermission</seealso></SDLWiki>
        public static extern void RequestAndroidPermission();

        /// <summary>
        /// <para>Trigger the Android system back button behavior.</para>
        /// </summary>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SendAndroidBackButton">SDL_SendAndroidBackButton</seealso></SDLWiki>
        public static extern void SendAndroidBackButton();

        /// <summary>
        /// <para>Send a user command to SDLActivity.</para>
        /// </summary>
        /// <remarks>
        /// <para>Override "boolean onUnhandledMessage(Message msg)" to handle the message.</para>
        /// </remarks>
        /// <param name="command">user command that must be greater or equal to 0x8000.</param>
        /// <param name="param">user parameter.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SendAndroidMessage">SDL_SendAndroidMessage</seealso></SDLWiki>
        public static extern void SendAndroidMessage();

        /// <summary>
        /// <para>Use this function to set the animation callback on Apple iOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>The function prototype for <c>callback</c> is:</para>
        /// <code language="c">
        /// void callback(void *callbackParam);
        /// </code>
        /// <para>Where its parameter, <c>callbackParam</c>, is what was passed as <c>callbackParam</c> to <see cref="SetiOsAnimationCallback"/>.</para>
        /// <para>This function is only available on Apple iOS.</para>
        /// <para>For more information see:</para>
        /// <para>https://wiki.libsdl.org/SDL3/README-ios</para>
        /// <para>Note that if you use the "main callbacks" instead of a standard C <c>main</c> function, you don't have to use this API, as SDL will manage this for you.</para>
        /// <para>Details on main callbacks are here:</para>
        /// <para>https://wiki.libsdl.org/SDL3/README-main-functions</para>
        /// </remarks>
        /// <param name="window">the window for which the animation callback should be set.</param>
        /// <param name="interval">the number of frames after which **callback** will be called.</param>
        /// <param name="callback">the function to call for every frame.</param>
        /// <param name="callbackParam">a pointer that is passed to <c>callback</c>.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetiOSAnimationCallback">SDL_SetiOSAnimationCallback</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Apple.SetEventPump">SetEventPump</see></seealso>
        public static extern void SetiOSAnimationCallback();

        /// <summary>
        /// <para>Use this function to enable or disable the SDL event pump on Apple iOS.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function is only available on Apple iOS.</para>
        /// </remarks>
        /// <param name="enabled">true to enable the event pump, false to disable it.</param>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetiOSEventPump">SDL_SetiOSEventPump</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Apple.SetAnimationCallback">SetAnimationCallback</see></seealso>
        public static extern void SetiOSEventPump();

        /// <summary>
        /// <para>Sets the UNIX nice value for a thread.</para>
        /// </summary>
        /// <remarks>
        /// <para>This uses setpriority() if possible, and RealtimeKit if available.</para>
        /// </remarks>
        /// <param name="threadID">the Unix thread ID to change priority of.</param>
        /// <param name="priority">the new, Unix-specific, priority value.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetLinuxThreadPriority">SDL_SetLinuxThreadPriority</seealso></SDLWiki>
        public static extern void SetLinuxThreadPriority();

        /// <summary>
        /// <para>Sets the priority (not nice level) and scheduling policy for a thread.</para>
        /// </summary>
        /// <remarks>
        /// <para>This uses setpriority() if possible, and RealtimeKit if available.</para>
        /// </remarks>
        /// <param name="threadID">the Unix thread ID to change priority of.</param>
        /// <param name="sdlPriority">the new <see cref="CSDL.Threads.Thread.Priority">Priority</see> value.</param>
        /// <param name="schedPolicy">the new scheduling policy (SCHED_FIFO, SCHED_RR, SCHED_OTHER, etc...).</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetLinuxThreadPriorityAndPolicy">SDL_SetLinuxThreadPriorityAndPolicy</seealso></SDLWiki>
        public static extern void SetLinuxThreadPriorityAndPolicy();

        /// <summary>
        /// <para>Set a callback for every Windows message, run before TranslateMessage().</para>
        /// </summary>
        /// <remarks>
        /// <para>The callback may modify the message, and should return true if the message should continue to be processed, or false to prevent further processing.</para>
        /// </remarks>
        /// <param name="callback">the <c>SDL_WindowsMessageHook</c> function to call.</param>
        /// <param name="userdata">a pointer to pass to every iteration of <c>callback</c>.</param>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetWindowsMessageHook">SDL_SetWindowsMessageHook</seealso></SDLWiki>
        /// <seealso><c>SDL_WindowsMessageHook</c></seealso>
        /// <seealso><see cref="CSDL.Hints.WindowsEnableMessageloop">WindowsEnableMessageloop</see></seealso>
        public static extern void SetWindowsMessageHook();

        /// <summary>
        /// <para>Set a callback for every X11 event.</para>
        /// </summary>
        /// <remarks>
        /// <para>The callback may modify the event, and should return true if the event should continue to be processed, or false to prevent further processing.</para>
        /// </remarks>
        /// <param name="callback">the <c>SDL_X11EventHook</c> function to call.</param>
        /// <param name="userdata">a pointer to pass to every iteration of <c>callback</c>.</param>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetX11EventHook">SDL_SetX11EventHook</seealso></SDLWiki>
        public static extern void SetX11EventHook();

        /// <summary>
        /// <para>Shows an Android toast notification.</para>
        /// </summary>
        /// <remarks>
        /// <para>Toasts are a sort of lightweight notification that are unique to Android.</para>
        /// <para>https://developer.android.com/guide/topics/ui/notifiers/toasts</para>
        /// <para>Shows toast in UI thread.</para>
        /// <para>For the <c>gravity</c> parameter, choose a value from here, or -1 if you don't have a preference:</para>
        /// <para>https://developer.android.com/reference/android/view/Gravity</para>
        /// </remarks>
        /// <param name="message">text message to be shown.</param>
        /// <param name="duration">0=short, 1=long.</param>
        /// <param name="gravity">where the notification should appear on the screen.</param>
        /// <param name="xoffset">set this parameter only when gravity >=0.</param>
        /// <param name="yoffset">set this parameter only when gravity >=0.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_ShowAndroidToast">SDL_ShowAndroidToast</seealso></SDLWiki>
        public static extern void ShowAndroidToast();
    }
